import { describe, it, expect } from "vitest";
import * as THREE from "three";
import { createHeroScene } from "../src/scene.js";

describe("createHeroScene", () => {
  it("returns a THREE.Scene", () => {
    const scene = createHeroScene();
    expect(scene).toBeInstanceOf(THREE.Scene);
  });

  it("contains a mesh named 'product'", () => {
    const scene = createHeroScene();
    const product = scene.getObjectByName("product");
    expect(product).toBeDefined();
    expect(product).toBeInstanceOf(THREE.Mesh);
  });

  it("the product mesh uses a TorusKnot geometry", () => {
    const scene = createHeroScene();
    const product = scene.getObjectByName("product");
    expect(product.geometry).toBeInstanceOf(THREE.TorusKnotGeometry);
  });

  it("contains exactly two lights", () => {
    const scene = createHeroScene();
    const lights = [];
    scene.traverse((obj) => {
      if (obj.isLight) lights.push(obj);
    });
    expect(lights).toHaveLength(2);
  });

  it("contains a ground disc mesh", () => {
    const scene = createHeroScene();
    let found = false;
    scene.traverse((obj) => {
      if (obj.isMesh && obj.geometry instanceof THREE.CircleGeometry) found = true;
    });
    expect(found).toBe(true);
  });
});

