import * as THREE from "three";

/**
 * Builds the hero scene graph: a torus-knot "product" mesh,
 * a ground disc, and two lights. Pure — no DOM or renderer
 * required, so it is fully unit-testable headless.
 */
export function createHeroScene() {
  const scene = new THREE.Scene();

  // Product: torus knot at the center of the frame.
  const productGeometry = new THREE.TorusKnotGeometry(1, 0.32, 160, 24);
  const productMaterial = new THREE.MeshStandardMaterial({
    color: 0x8b5cf6,
    metalness: 0.65,
    roughness: 0.25,
  });
  const product = new THREE.Mesh(productGeometry, productMaterial);
  product.name = "product";
  product.position.set(0, 1.4, 0);
  scene.add(product);

  // Ground disc beneath the product.
  const groundGeometry = new THREE.CircleGeometry(6, 64);
  const groundMaterial = new THREE.MeshStandardMaterial({
    color: 0x111318,
    metalness: 0.2,
    roughness: 0.85,
  });
  const ground = new THREE.Mesh(groundGeometry, groundMaterial);
  ground.name = "ground";
  ground.rotation.x = -Math.PI / 2;
  scene.add(ground);

  // Light one: key directional light.
  const keyLight = new THREE.DirectionalLight(0xffffff, 2.2);
  keyLight.position.set(4, 6, 5);
  scene.add(keyLight);

  // Light two: fill point light with a warm tint.
  const fillLight = new THREE.PointLight(0xff9d5c, 30, 25);
  fillLight.position.set(-5, 3, -4);
  scene.add(fillLight);

  return scene;
}

