import * as THREE from "three";
import { createHeroScene } from "./scene.js";

/**
 * Entry point. The scene graph is built unconditionally (it is pure
 * and DOM-free), but the WebGLRenderer is only created when a canvas
 * is actually present, and guarded so this module never throws in a
 * headless environment.
 */
const canvas = document.querySelector("canvas#hero");

if (!canvas) {
  console.warn("[hero] No #hero canvas found; skipping renderer setup.");
} else {
  try {
    const scene = createHeroScene();
    const camera = new THREE.PerspectiveCamera(
      45,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 3.2, 7);
    camera.lookAt(0, 1.2, 0);

    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    scene.background = new THREE.Color(0x0b0d12);

    function tick(elapsed) {
      const product = scene.getObjectByName("product");
      if (product) {
        product.rotation.y = elapsed * 0.4;
        product.rotation.x = Math.sin(elapsed * 0.3) * 0.25;
      }
      renderer.render(scene, camera);
    }

    renderer.setAnimationLoop(tick);

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  } catch (err) {
    // WebGL unavailable / context creation failed — degrade gracefully.
    console.error("[hero] Failed to initialize WebGL renderer:", err);
  }
}

