import { describe, it, expect } from "vitest";
import { readFileSync, existsSync, statSync } from "node:fs";
import { resolve } from "node:path";

const distDir = resolve(process.cwd(), "dist");

describe("vite build output", () => {
  it("dist/index.html exists", () => {
    expect(existsSync(resolve(distDir, "index.html"))).toBe(true);
  });

  it("contains a script tag referencing an /assets/ js file", () => {
    const html = readFileSync(resolve(distDir, "index.html"), "utf8");
    const match = html.match(/<script[^>]+src="(\/assets\/[^"]+\.js)"/);
    expect(match, "no <script src=\"/assets/*.js\"> found in built index.html").not.toBeNull();
    expect(match[1]).toMatch(/^\/assets\/.+\.js$/);
  });

  it("the referenced asset file exists and is non-empty", () => {
    const html = readFileSync(resolve(distDir, "index.html"), "utf8");
    const match = html.match(/<script[^>]+src="(\/assets\/[^"]+\.js)"/);
    expect(match).not.toBeNull();

    const assetPath = resolve(distDir, match[1].replace(/^\//, ""));
    expect(existsSync(assetPath)).toBe(true);

    const stats = statSync(assetPath);
    expect(stats.isFile()).toBe(true);
    expect(stats.size).toBeGreaterThan(0);
  });
});

